// Independent fixture matrices for qr.test.ts (I2 of task-8's fix round 1).
//
// Each fixture's `rows` came from ZXing-C++ (via the `zxing-wasm` package,
// already present transitively in node_modules — not a project dependency;
// see rulings.md I2 for why this repo does not import it), run once from a
// scratch script outside this repo and pasted here as a literal, not
// generated at test time. The generating script forced the exact version
// and mask this encoder itself picks for each `text` (`version=<n>,ecLevel=
// M,dataMask=<n>` in ZXing's writer `options` string) so the two encoders'
// output is directly, bit-for-bit comparable rather than merely "both
// valid". Both `text`s are pure lowercase ASCII with no digits, so ZXing's
// own mode optimiser has no cheaper alternative to byte mode available and
// cannot silently pick a different segmentation than this encoder always
// uses — confirmed by first reproducing the mismatch that a digit-bearing
// fixture text produces (see the report) before settling on this text.
//
// `#` is a dark module, `.` is light, one row per string, one string per
// matrix row, top to bottom.

export interface QrFixture {
  text: string;
  version: number;
  /** The error-correction level; M when absent. */
  level?: "L" | "M";
  mask: number;
  rows: readonly string[];
}

